import{_ as t,o as n,c as s,ah as a}from"./chunks/framework.ChH6X6u6.js";const g=JSON.parse('{"title":"Vos enfants et leurs documents","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/parent/enfants-et-documents.md","filePath":"src/guide/parent/enfants-et-documents.md"}'),r={name:"guide/parent/enfants-et-documents.md"};function o(i,e,l,u,c,d){return n(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="vos-enfants-et-leurs-documents" tabindex="-1">Vos enfants et leurs documents <a class="header-anchor" href="#vos-enfants-et-leurs-documents" aria-label="Permalink to &quot;Vos enfants et leurs documents&quot;">​</a></h1><p>Cette page explique comment retrouver vos enfants dans ERA, consulter leur suivi scolaire et télécharger tous les documents qui les concernent.</p><h2 id="voir-vos-enfants" tabindex="-1">Voir vos enfants <a class="header-anchor" href="#voir-vos-enfants" aria-label="Permalink to &quot;Voir vos enfants&quot;">​</a></h2><p>La page <strong>Mes enfants</strong> (espace <strong>Accueil</strong>) liste tous les enfants rattachés à votre compte, chacun sous forme de carte. Chaque carte indique :</p><ul><li>sa classe ;</li><li>en orange, le nombre d&#39;<strong>absences à justifier</strong> : les absences non justifiées pour lesquelles vous n&#39;avez pas encore envoyé de justificatif (voir <a href="/era-guide/guide/parent/demarches.html">Démarches</a>) ;</li><li>la <strong>prochaine échéance</strong> de son échéancier, avec son montant et sa date, en rouge si elle est <strong>en retard</strong> ;</li><li>sa <strong>moyenne annuelle</strong> et son <strong>solde</strong> ;</li><li>ses <strong>dernières notes</strong>, avec la matière et la date.</li></ul><p>Cliquez sur une carte pour ouvrir la fiche complète de cet enfant.</p><p>Si aucun enfant n&#39;apparaît encore, votre établissement doit d&#39;abord rattacher votre compte à celui de votre enfant — ou vous pouvez le faire vous-même si cette fonctionnalité est activée (voir ci-dessous).</p><h2 id="rattacher-un-enfant-a-votre-compte" tabindex="-1">Rattacher un enfant à votre compte <a class="header-anchor" href="#rattacher-un-enfant-a-votre-compte" aria-label="Permalink to &quot;Rattacher un enfant à votre compte&quot;">​</a></h2><p>Si votre établissement a activé le rattachement en libre-service, un menu <strong>Rattacher un enfant</strong> apparaît en onglet à côté de <strong>Mes enfants</strong>. Pour lier un enfant déjà inscrit à votre compte :</p><ol><li>Ouvrez <strong>Rattacher un enfant</strong>.</li><li>Dans le formulaire de recherche, saisissez le <strong>Prénom</strong>, le <strong>Nom</strong> et la <strong>Date de naissance</strong> de l&#39;enfant, puis cliquez sur <strong>Rechercher</strong>.</li><li>Dans les résultats, cliquez sur <strong>Rattacher</strong> en face de l&#39;enfant concerné.</li><li>Choisissez votre <strong>Lien de parenté</strong> (Père, Mère, Tuteur légal ou Autre).</li><li>Cochez <strong>Contact principal</strong> si vous devez être le premier contact joignable pour cet enfant.</li><li>Cliquez sur <strong>Rattacher</strong> pour valider.</li></ol><p>L&#39;enfant apparaît ensuite dans la liste <strong>Enfants déjà rattachés</strong> de cette même page, et sur votre page <strong>Mes enfants</strong>.</p><div class="info custom-block"><p class="custom-block-title">Si le menu « Rattacher un enfant » n&#39;existe pas</p><p>C&#39;est que l&#39;établissement n&#39;a pas activé le rattachement en libre-service. Ce n&#39;est pas un problème sur votre compte : dans ce cas, le rattachement est fait par le secrétariat ou l&#39;administration, depuis le dossier de votre enfant. Contactez l&#39;établissement en indiquant le nom et la date de naissance de l&#39;enfant, et votre lien de parenté.</p></div><h2 id="consulter-le-suivi-d-un-enfant" tabindex="-1">Consulter le suivi d&#39;un enfant <a class="header-anchor" href="#consulter-le-suivi-d-un-enfant" aria-label="Permalink to &quot;Consulter le suivi d&#39;un enfant&quot;">​</a></h2><p>Sur la fiche d&#39;un enfant (accessible depuis <strong>Mes enfants</strong>), vous retrouvez, dans l&#39;ordre :</p><ul><li><strong>Notes</strong> — les moyennes par matière pour chaque période, avec la moyenne annuelle en haut de la section.</li><li><strong>Cahier de texte</strong> — la liste des cours donnés avec la date, la matière, le contenu et les devoirs demandés.</li><li><strong>Emploi du temps</strong> — le planning hebdomadaire de la classe de l&#39;enfant (jour, heure de début, heure de fin, matière).</li><li><strong>Internat</strong> — si votre enfant est interne, cette section indique son site, sa chambre et son lit, ainsi que ses présences à l&#39;internat.</li><li><strong>Présences</strong> — chaque jour avec son statut (Présent, Absent, Retard) et, le cas échéant, la note de justification.</li><li><strong>Incidents disciplinaires</strong> — date, gravité (Mineure, Majeure, Grave), description et sanction éventuelle.</li><li><strong>Conseils de discipline</strong> — les séances de conseil de discipline tenues pour cet enfant et leur décision (avertissement, blâme, exclusion temporaire ou définitive, ou non-lieu).</li></ul><h2 id="telecharger-les-documents-de-votre-enfant" tabindex="-1">Télécharger les documents de votre enfant <a class="header-anchor" href="#telecharger-les-documents-de-votre-enfant" aria-label="Permalink to &quot;Télécharger les documents de votre enfant&quot;">​</a></h2><p>Depuis la fiche de l&#39;enfant, vous pouvez télécharger :</p><ul><li><strong>Les bulletins</strong> — dans la section « Bulletins », cliquez sur <strong>Télécharger</strong> en face de la période souhaitée. Un bulletin n&#39;apparaît que lorsqu&#39;il a été publié par l&#39;établissement.</li><li><strong>Les reçus de paiement</strong> — dans l&#39;historique des paiements (section paiements), cliquez sur <strong>Télécharger le reçu</strong> en face d&#39;un paiement ; ce lien n&#39;apparaît que si un reçu a été généré pour ce paiement.</li><li><strong>Les procès-verbaux de conseil de discipline</strong> — dans la section « Conseils de discipline », cliquez sur <strong>Télécharger le procès-verbal</strong> en face d&#39;un conseil déjà décidé.</li><li><strong>Les pièces jointes du cahier de texte</strong> — quand un cours du cahier de texte a un document joint, un lien <strong>Document</strong> apparaît en face de la ligne correspondante ; cliquez pour l&#39;ouvrir ou le télécharger.</li></ul><h2 id="exporter-l-emploi-du-temps" tabindex="-1">Exporter l&#39;emploi du temps <a class="header-anchor" href="#exporter-l-emploi-du-temps" aria-label="Permalink to &quot;Exporter l&#39;emploi du temps&quot;">​</a></h2><p>Pour importer l&#39;emploi du temps de votre enfant dans votre propre calendrier (Google Calendar, Apple Calendar, Outlook…) :</p><ol><li>Sur la fiche de l&#39;enfant, allez dans la section <strong>Emploi du temps</strong>.</li><li>Cliquez sur <strong>Exporter vers un calendrier</strong>.</li><li>Un fichier <code>.ics</code> est téléchargé ; ouvrez-le ou importez-le dans votre application de calendrier habituelle pour ajouter les cours de votre enfant à votre agenda.</li></ol>',21)])])}const m=t(r,[["render",o]]);export{g as __pageData,m as default};
